function sharedTimerSeconds(timer, serverNow) {
  if (!timer) return 1500;
  return Math.min(timer.remaining_seconds, Math.max(0, timer.running && timer.deadline ? Math.ceil((Date.parse(timer.deadline) - serverNow) / 1e3) : timer.remaining_seconds));
}
function normalizeMeetUrl(value) {
  if (!value?.trim()) return null;
  let url;
  try {
    url = new URL(value.trim());
  } catch {
    throw Error("Peg\xE1 un enlace v\xE1lido de Google Meet.");
  }
  if (url.protocol !== "https:" || url.hostname !== "meet.google.com" || url.port || url.username || url.password || !/^\/[a-z]{3}-[a-z]{4}-[a-z]{3}\/?$/.test(url.pathname))
    throw Error("Us\xE1 un enlace https://meet.google.com/abc-defg-hij.");
  return "https://meet.google.com" + url.pathname.replace(/\/$/, "");
}
function sessionStateLabel(status) {
  return {
    scheduled: "Programada",
    active: "En curso",
    completed: "Completada",
    cancelled: "Cancelada"
  }[status];
}
