// source:C:\Users\tavan\Documents\Codex\2026-09-05\haz\outputs\compa-virtual\packages\domain\src\shared-rooms.ts
function sharedSeats(id2) {
  const positions = [];
  if (id2 === "living" || id2 === "terrace") {
    for (const x of [-1.7, -0.56, 0.56, 1.7]) positions.push([x, 1.52, 0]);
    positions.push([-2.6, -0.78, -0.72], [2.6, -0.78, 0.72]);
  } else if (id2 === "patio") {
    for (const a of [0, Math.PI / 2, Math.PI, Math.PI * 1.5]) positions.push([-1.3 + Math.sin(a) * 1.33, -0.25 - Math.cos(a) * 1.33, a + Math.PI]);
    positions.push([1.48, 1.1, 0], [2.34, 1.1, 0]);
  } else {
    for (const [y, a] of [[-1.3, Math.PI], [1.25, 0]]) for (const x of [-1.65, 0, 1.65]) {
      if (id2 === "library" && Math.abs(x) > 1 && y > 0) continue;
      positions.push([x, y, a]);
    }
    if (id2 === "library") positions.push([-2.88, 1.62, 0], [2.88, 1.62, 0]);
  }
  return positions.map(([x, y, yaw], i) => ({ id: `SEAT_0${i + 1}`, position: [x, 0.46, -y], yaw, height: 0.46 }));
}
