function books(m, origin, count = 5, standing = true) {
  const colors = [
    "#718da0",
    "#d99978",
    "#b5b793",
    "#bca6c1",
    "#d9ba73",
    "#586982"
  ];
  for (let i = 0; i < count; i++) {
    const height = 0.23 + i % 3 * 0.035;
    const pos = standing ? [origin[0] + i * 0.069, origin[1] + height / 2, origin[2]] : [origin[0] + i % 2 * 0.025, origin[1] + i * 0.045, origin[2]];
    m.box(
      standing ? [0.057, height, 0.16] : [0.28, 0.034, 0.21],
      colors[i % colors.length],
      pos,
      5e-3
    );
    if (standing)
      m.box(
        [0.041, 8e-3, 4e-3],
        cream,
        [pos[0], pos[1] + 0.07, pos[2] + 0.083],
        0
      );
    else
      m.box([0.254, 0.017, 6e-3], cream, [pos[0], pos[1], pos[2] + 0.108], 0);
  }
}
